<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,fmt} from '../api'
import {useWorkspace} from '../store'
import Icon from '../components/Icon.vue'
const store=useWorkspace(),items=ref<any[]>([]),total=ref(0),page=ref(1),search=ref(''),dialog=ref(false),saving=ref(false),form=ref<any>({}),memberProject=ref<any>(null),members=ref<any[]>([]),memberForm=ref({username:'',role:'viewer'})
async function load(){const {data}=await api.get('projects/',{params:{search:search.value,page:page.value}});items.value=data.results;total.value=data.count}
function edit(item?:any){form.value=item?{...item}:{name:'',key:'',description:''};dialog.value=true}
async function save(){if(!form.value.name||!form.value.key){ElMessage.warning('请填写项目名称和标识');return}saving.value=true;try{const {data}=await(form.value.id?api.patch(`projects/${form.value.id}/`,form.value):api.post('projects/',form.value));dialog.value=false;await store.loadProjects();store.projectId=data.id;await load();ElMessage.success('项目已保存')}finally{saving.value=false}}
async function remove(p:any){try{await ElMessageBox.confirm(`将永久删除「${p.name}」及其全部配置、资产和报告，是否继续？`,'删除项目',{type:'warning',confirmButtonText:'确认删除'})}catch{return}await api.delete(`projects/${p.id}/`);await store.loadProjects();if(items.value.length===1&&page.value>1)page.value--;load()}
async function showMembers(p:any){memberProject.value=p;members.value=(await api.get(`projects/${p.id}/members/`)).data}
async function addMember(){if(!memberForm.value.username)return;await api.post(`projects/${memberProject.value.id}/members/`,memberForm.value);memberForm.value.username='';await showMembers(memberProject.value);ElMessage.success('成员权限已更新')}
async function removeMember(m:any){await api.delete(`projects/${memberProject.value.id}/members/`,{data:{username:m.username}});showMembers(memberProject.value)}
onMounted(load)
</script>
<template><div><div class="page-heading"><div><div class="heading-eyebrow">TEAM WORKSPACE</div><h1>{{ $t('项目管理') }}</h1><p>{{ $t('为每个项目建立独立的测试空间，统一管理资产与团队权限。') }}</p></div><el-button type="primary" @click="edit()"><Icon name="Plus"/>{{ $t('创建项目') }}</el-button></div><section class="panel"><div class="list-toolbar"><h3>{{ $t('全部项目') }}<span class="count-badge">{{total}}</span></h3><div class="inline-actions"><el-input v-model="search" :placeholder="$t('搜索项目名称或标识')" clearable @keyup.enter="page=1;load()" @clear="page=1;load()"/><el-button @click="page=1;load()">{{ $t('查询') }}</el-button></div></div><el-table :data="items"><el-table-column :label="$t('项目')" min-width="230"><template #default="{row}"><div class="table-title"><span class="large-icon violet"><Icon name="FolderOpened" :size="24"/></span><div><strong>{{row.name}}</strong><small>{{row.key}}</small></div></div></template></el-table-column><el-table-column prop="description" :label="$t('项目描述')" min-width="230" show-overflow-tooltip/><el-table-column prop="case_count" :label="$t('用例')" width="70"/><el-table-column :label="$t('我的角色')" width="100"><template #default="{row}">{{({owner:'管理员',editor:'编辑者',viewer:'观察者'} as any)[row.role]}}</template></el-table-column><el-table-column :label="$t('操作')" width="240"><template #default="{row}"><el-button link type="primary" @click="store.projectId=row.id;$router.push('/')">{{ $t('进入') }}</el-button><template v-if="row.role==='owner'"><el-button link @click="edit(row)">{{ $t('编辑') }}</el-button><el-button link @click="showMembers(row)">{{ $t('成员') }}</el-button><el-button link type="danger" @click="remove(row)">{{ $t('删除') }}</el-button></template></template></el-table-column><template #empty><el-empty :description="$t('尚无项目，创建一个项目开始测试')"/></template></el-table><div class="pagination"><span>共 {{total}} 个项目</span><el-pagination v-model:current-page="page" :total="total" layout="prev, pager, next" @current-change="load"/></div></section>
<el-dialog v-model="dialog" :title="form.id?'编辑项目':'创建项目'" width="540px"><el-form label-position="top"><el-form-item :label="$t('项目名称 *')"><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item :label="$t('项目标识 *')"><el-input v-model="form.key" maxlength="20" :placeholder="$t('如 SHOP，仅英文字母、数字、下划线和连字符')"/></el-form-item><el-form-item :label="$t('项目描述')"><el-input v-model="form.description" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">{{ $t('取消') }}</el-button><el-button type="primary" :loading="saving" @click="save">{{ $t('保存项目') }}</el-button></template></el-dialog>
<el-dialog :model-value="!!memberProject" :title="$t('项目成员与权限')" width="620px" @close="memberProject=null"><template v-if="memberProject"><p class="helper">所有者：{{memberProject.owner_name}}。编辑者可管理资产与执行任务；观察者仅可查看和下载。用户账号需先由系统管理员创建。</p><div class="inline-actions"><el-input v-model="memberForm.username" :placeholder="$t('已有用户的用户名')"/><el-select v-model="memberForm.role" style="width:150px"><el-option :label="$t('观察者')" value="viewer"/><el-option :label="$t('编辑者')" value="editor"/></el-select><el-button type="primary" @click="addMember">{{ $t('添加 / 更新') }}</el-button></div><el-table :data="members"><el-table-column prop="username" :label="$t('用户名')"/><el-table-column :label="$t('角色')"><template #default="{row}">{{row.role==='editor'?'编辑者':'观察者'}}</template></el-table-column><el-table-column :label="$t('操作')" width="70"><template #default="{row}"><el-button link type="danger" @click="removeMember(row)">{{ $t('移除') }}</el-button></template></el-table-column></el-table></template></el-dialog>
</div></template>
